CREATE VIEW v_d59_ends AS SELECT DISTINCT tid, FIRST_VALUE(status) OVER (PARTITION BY tid ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS start_st, LAST_VALUE(status) OVER (PARTITION BY tid ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS end_st
FROM d59_ticket;
INSERT OR IGNORE INTO first_last_value_win_d59_meta VALUES ('module', 'first_last_value_win_d59');
